export type User = {id: string; name: string; email: string; role: 'admin' | 'member'};
const rows = new Map<string, User>();
export const store = {
  list: (q?: string) => [...rows.values()].filter((u) => !q || u.name.includes(q)),
  get: (id: string) => rows.get(id),
  put: (u: User) => { rows.set(u.id, u); return u; },
  remove: (id: string) => rows.delete(id),
};
